def largest_divisor(n: int) -> int:
    """ For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largest_divisor(15)
    5
    """
    if n <= 1:
        return 1
    i = 2
    while i * i <= n:
        if n % i == 0:
            return n // i
        i += 1
    return 1

def flip_case(string: str) -> str:
    """ For a given string, flip lowercase characters to uppercase and uppercase to lowercase.
    >>> flip_case('Hello')
    'hELLO'
    """
    return string.swapcase()

import math


def poly(xs: list, x: float):
    """
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
    """
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])


def _min_abs_arg(xs: list):
    """Fallback for inputs outside the stated guarantee (no sign-changing
    root, e.g. only even-multiplicity roots): return the argument that
    minimizes |poly|, via a coarse geometric grid plus local refinement."""
    def safe(x):
        try:
            return abs(poly(xs, x))
        except OverflowError:
            return math.inf

    # Geometric grid covering ~1e-12 .. ~1e307 in ~19% steps.
    grid = [-(2.0 ** (k / 4.0)) for k in range(4080, -161, -1)]
    grid.append(0.0)
    grid += [2.0 ** (k / 4.0) for k in range(-160, 4081)]

    best_i, best_v = 0, safe(grid[0])
    for i in range(1, len(grid)):
        v = safe(grid[i])
        if v < best_v:
            best_i, best_v = i, v
    if best_v == math.inf:
        return 0.0

    # Refine |poly| minimum inside the best grid cell (ternary search).
    a = grid[best_i - 1] if best_i > 0 else grid[0]
    b = grid[best_i + 1] if best_i + 1 < len(grid) else grid[-1]
    for _ in range(300):
        m1 = a + (b - a) / 3.0
        m2 = b - (b - a) / 3.0
        if safe(m1) < safe(m2):
            b = m2
        else:
            a = m1
    x = (a + b) / 2.0
    return x if safe(x) <= best_v else grid[best_i]


def find_zero(xs: list):
    """ xs are coefficients of a polynomial.
    find_zero find x such that poly(x) = 0.
    find_zero returns only only zero point, even if there are many.
    Moreover, find_zero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> round(find_zero([1, 2]), 2) # f(x) = 1 + 2x
    -0.5
    >>> round(find_zero([-6, 11, -6, 1]), 2) # (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
    """
    begin, end = -1.0, 1.0
    fb, fe = poly(xs, begin), poly(xs, end)

    # Phase 1: bracket a root. An even number of coefficients means an odd
    # degree, so the polynomial takes opposite signs at -inf and +inf;
    # doubling the bracket eventually straddles a root.
    bracket_found = False
    for _ in range(2000):
        if fb == 0:
            return begin
        if fe == 0:
            return end
        if (fb > 0) != (fe > 0):
            bracket_found = True
            break
        if math.isinf(begin) or math.isinf(end):
            break
        begin *= 2.0
        end *= 2.0
        try:
            fb, fe = poly(xs, begin), poly(xs, end)
        except OverflowError:
            break  # magnitudes overflowed before a sign change
    if not bracket_found:
        # No sign change exists (input outside the stated guarantee):
        # minimize |poly| instead of looping forever.
        return _min_abs_arg(xs)

    # Phase 2: bisection, keeping the sign change between begin and end.
    for _ in range(200):
        mid = (begin + end) / 2.0
        if math.isnan(mid):
            mid = 0.0  # begin = -inf, end = +inf
        if mid == begin or mid == end:
            break  # interval is at float precision
        fm = poly(xs, mid)
        if fm == 0:
            return mid
        if (fm > 0) == (fb > 0):
            begin, fb = mid, fm
        else:
            end, fe = mid, fm

    return begin if abs(fb) <= abs(fe) else end

def unique(l: list):
    """Return sorted unique elements in a list
    >>> unique([5, 3, 5, 2, 3, 3, 9, 0, 123])
    [0, 2, 3, 5, 9, 123]
    """
    return sorted(set(l))


