    assert set(similar_elements((3, 4, 5, 6), (5, 7, 4, 10))) == set((4, 5))
    assert set(similar_elements((1, 2, 3, 4), (5, 2, 3, 9))) == set((3, 2))
    assert set(similar_elements((1, 2, 3), (4, 5, 6))) == set()
    print("All tests passed.")

