def count_Substrings(s):
    """Count the number of substrings of s whose digit sum equals their length.

    Example:
        count_Substrings('112112') == 6
    """
    count = 0
    for i in range(len(s)):
        digit_sum = 0
        for j in range(i, len(s)):
            digit_sum += int(s[j])
            if digit_sum == j - i + 1:
                count += 1
    return count

