def is_samepatterns(elems, patterns):
    """Check whether `elems` follows the sequence given in `patterns`.

    Two sequences follow the same pattern if there is a bijection between
    the elements of `elems` and the elements of `patterns` such that each
    element always maps to the same pattern element (and vice versa).

    >>> is_samepatterns(["red", "green", "green"], ["a", "b", "b"])
    True
    >>> is_samepatterns(["red", "green", "green"], ["a", "b", "c"])
    False
    >>> is_samepatterns(["a", "a", "a"], ["x", "y", "x"])
    False
    """
    if len(elems) != len(patterns):
        return False

    elem_to_pattern = {}
    pattern_to_elem = {}

    for elem, pattern in zip(elems, patterns):
        if elem in elem_to_pattern:
            if elem_to_pattern[elem] != pattern:
                return False
        else:
            elem_to_pattern[elem] = pattern

        if pattern in pattern_to_elem:
            if pattern_to_elem[pattern] != elem:
                return False
        else:
            pattern_to_elem[pattern] = elem

    return True

