def frequency_lists(list1):
    """Find frequency of each element in a flattened list of lists.

    Args:
        list1: A list of lists.

    Returns:
        A dictionary mapping each element to its frequency across all sublists.
    """
    freq = {}
    for sublist in list1:
        for item in sublist:
            freq[item] = freq.get(item, 0) + 1
    return freq

