def common_in_nested_lists(nested_lists):
    """Find the common elements in given nested lists.

    Args:
        nested_lists: A list of lists.

    Returns:
        A list of elements common to all the inner lists.
    """
    if not nested_lists:
        return []
    common = set(nested_lists[0])
    for lst in nested_lists[1:]:
        common &= set(lst)
    return list(common)


