def find_lucas(n):
    """Return the n'th Lucas number.

    Lucas numbers: L(0) = 2, L(1) = 1, and L(n) = L(n-1) + L(n-2).
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    a, b = 2, 1  # L(0), L(1)
    for _ in range(n):
        a, b = b, a + b
    return a

