def sumofFactors(n):
    """Return the sum of the even factors of n."""
    total = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            if i % 2 == 0:
                total += i
            other = n // i
            if other != i and other % 2 == 0:
                total += other
        i += 1
    return total


