    assert sumofFactors(18) == 26
    assert sumofFactors(30) == 48   # 2 + 6 + 10 + 30
    assert sumofFactors(6) == 8     # 2 + 6
    assert sumofFactors(9) == 0     # no even factors
    assert sumofFactors(1) == 0
    print("All tests passed.")

