def find_kth(arr1, arr2, k):
    """Find the k-th (1-indexed) smallest element from two sorted arrays.

    Uses a divide-and-conquer strategy that runs in O(log k) time by
    discarding, at each step, a prefix of one array that is guaranteed
    to lie entirely within the k smallest elements.

    >>> find_kth([2, 3, 6, 7, 9], [1, 4, 8, 10], 5)
    6
    """
    if k < 1 or k > len(arr1) + len(arr2):
        raise IndexError("k is out of range for the given arrays")

    def kth(a1, a2, k):
        # k is 1-indexed within the remaining elements of a1/a2.
        if not a1:
            return a2[k - 1]
        if not a2:
            return a1[k - 1]
        if k == 1:
            return min(a1[0], a2[0])

        # Try to discard the first k//2 elements of each array
        # (as many as each array actually has).
        i = min(len(a1), k // 2)
        j = min(len(a2), k // 2)

        if a1[i - 1] <= a2[j - 1]:
            # First i elements of a1 are among the k smallest; drop them.
            return kth(a1[i:], a2, k - i)
        else:
            # First j elements of a2 are among the k smallest; drop them.
            return kth(a1, a2[j:], k - j)

    return kth(list(arr1), list(arr2), k)


if __name__ == "__main__":
    assert find_kth([2, 3, 6, 7, 9], [1, 4, 8, 10], 5) == 6
    print("All tests passed.")

