def get_coordinates(test_tup):
    """Extract all the adjacent coordinates of the given coordinate tuple.

    For a coordinate tuple of any dimension, returns every coordinate
    obtained by shifting each component by -1, 0, or +1 (the surrounding
    grid, including the original point).

    >>> get_coordinates((3, 4))
    [[2, 3], [2, 4], [2, 5], [3, 3], [3, 4], [3, 5], [4, 3], [4, 4], [4, 5]]
    """
    def adjac(ele, sub):
        if not ele:
            yield list(sub)
        else:
            for idx in range(ele[0] - 1, ele[0] + 2):
                yield from adjac(ele[1:], sub + [idx])

    return list(adjac(test_tup, []))


if __name__ == "__main__":
    assert get_coordinates((3, 4)) == [[2, 3], [2, 4], [2, 5], [3, 3], [3, 4],
                                       [3, 5], [4, 3], [4, 4], [4, 5]]
    assert get_coordinates((1, 2, 3)) == [
        [x, y, z]
        for x in range(0, 3)
        for y in range(1, 4)
        for z in range(2, 5)
    ]
    assert get_coordinates((5,)) == [[4], [5], [6]]
    print("All tests passed.")

